class Gisafirst {
    static int v = 1;
    public static void main(String[] args) {
        int a[][] = new int[3][3];
        init(a);
        data(a);
        print(a);
    }
    static void init(int a[][]) {
        for(int i=0; i<3; i++) {
            for(int j=0; j<3; j++) {
                a[i][j] = 0;
            }
        }
    }
    static void data(int a[][]) {
        for(int i=0; i<3; i++) {
            for(int j=i; j<3; j++) {
                a[i][j] = v;
                v++;
            }
        }
    }
    static void print(int a[][]) {
        for(int i=0; i<3; i++) {
            for(int j=0; j<3; j++) {
                if(a[i][j] == 0) {
                    System.out.print(" ");
                }
                else {
                    System.out.printf("%d", a[i][j]);
                }
            }
            System.out.println("");
        }
    }
}

